  'projectFile.create.directionHelp': { 'zh-Hans': '写下想要的画面和节奏，Mio 会参考它', 'zh-Hant': '寫下想要的畫面和節奏，Mio 會參考它', en: 'Describe the look and pace you want; Mio uses it as a reference', ja: '目指す映像やテンポを書いておくと、Mio が参考にします' },
  'projectFile.create.directionPlaceholder': { 'zh-Hans': '例如：雨夜城市，霓虹倒影，冷色调，节奏舒缓', 'zh-Hant': '例如：雨夜城市，霓虹倒影，冷色調，節奏舒緩', en: 'For example: a city on a rainy night, neon reflections, cool tones, a slow pace', ja: '例：雨の夜の街、ネオンの映り込み、寒色系、ゆったりしたテンポ' },
